var $bm_rt;
var freq, amp, n, pts, inT, outT, closed, newPoints, newIn, newOut, i, ox, oy;
freq = 6;
amp = 1;
n = Math.floor($bm_mul(time, freq));
pts = points();
inT = inTangents();
outT = outTangents();
closed = isClosed();
newPoints = [];
newIn = [];
newOut = [];
for (i = 0; i < pts.length; i++) {
    seedRandom($bm_sum($bm_mul(n, 10000), i), true);
    ox = random($bm_neg(amp), amp);
    oy = random($bm_neg(amp), amp);
    newPoints.push([
        $bm_sum(pts[i][0], ox),
        $bm_sum(pts[i][1], oy)
    ]);
    newIn.push(inT[i]);
    newOut.push(outT[i]);
}
$bm_rt = createPath(newPoints, newIn, newOut, closed);

